// With annotation: compiler enforces one abstract method
@FunctionalInterface
public interface Transformer<T, R> {
    R transform(T input);
    // Adding another abstract method would be a COMPILE ERROR
    // void anotherMethod(); // ERROR: invalid @FunctionalInterface

    // Default and static methods are fine
    default Transformer<T, R> andLog() { /* ... */ return this; }
}

// Without annotation: still works as a lambda target
public interface StringProcessor {
    String process(String s); // one abstract method — still functional
}
StringProcessor upper = String::toUpperCase; // works!
