Function<String, Integer> length = String::length;
Function<Integer, String> format = n -> "Length: " + n;

// andThen: apply length first, then format
Function<String, String> describe = length.andThen(format);
describe.apply("hello"); // "Length: 5"

// compose: apply format first, then length — TYPE ERROR in this case
// length.compose(format) would need Integer→String→Integer
